// Modelo único de e-mail com a marca do Instituto Modal, usado pelos fluxos do n8n.
// O gerador embute este arquivo no nó Code antes da lógica de cada fluxo.
// Cuidados: tabelas e estilos em linha (leitores de e-mail ignoram CSS moderno);
// a logo fica numa caixa branca que não inverte no tema escuro (cor + imagem de fundo brancas).

const MARCA = {
  azul: '#00004d',
  laranja: '#ff9900',
  cinza: '#666666',
  fundo: '#f3f4f8',
  borda: '#e3e5ee',
  fonte: "Ubuntu, Lato, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
  logo: 'https://assets.modal.org.br/logo/png/modal_logo_simplificada_512px.png',
  site: 'https://modal.org.br',
};

function escHtml(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Etiqueta de situação. tipo: 'antes' (cinza) ou 'depois' (laranja).
function pilula(texto, tipo) {
  const cores = tipo === 'depois'
    ? 'background:#fff3e0;color:#7a4300;border:1px solid #ff9900;'
    : 'background:#eef0f5;color:#3d3f57;border:1px solid #d6d9e4;';
  return `<span class="pil-${tipo === 'depois' ? 'd' : 'a'}" style="display:inline-block;padding:3px 10px;border-radius:999px;font-size:13px;font-weight:700;${cores}">${escHtml(texto)}</span>`;
}

// Caixa de destaque. tom: 'teste' (amarelo) ou 'erro' (vermelho).
function aviso(texto, tom) {
  const cores = tom === 'erro'
    ? 'background:#fdecec;border-left:4px solid #c62828;color:#5c1010;'
    : 'background:#fff8e1;border-left:4px solid #ff9900;color:#5c3d00;';
  return `<div class="aviso" style="margin:18px 0 0;padding:12px 14px;border-radius:4px;font-size:14px;line-height:1.5;${cores}">${texto}</div>`;
}

function paragrafo(html) {
  return `<p class="txt" style="margin:0 0 14px;font-size:15px;line-height:1.6;color:#1f2033;white-space:pre-line;">${html}</p>`;
}

// Monta o e-mail. blocos: HTML já escapado, feito com paragrafo(), pilula() e aviso().
function layoutEmail({ etiqueta, titulo, previa, blocos, acao, rodape }) {
  const botao = acao
    ? `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:22px 0 4px;"><tr><td class="btn" bgcolor="${MARCA.azul}" style="border-radius:6px;background:${MARCA.azul};">
<a href="${escHtml(acao.url)}" style="display:inline-block;padding:12px 22px;font-family:${MARCA.fonte};font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:6px;">${escHtml(acao.rotulo)}</a>
</td></tr></table>`
    : '';
  return `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<meta name="supported-color-schemes" content="light dark">
<title>${escHtml(titulo)}</title>
<link href="https://fonts.googleapis.com/css2?family=Ubuntu:wght@400;700&display=swap" rel="stylesheet">
<style>
  body { margin:0; padding:0; }
  @media (max-width: 620px) {
    .cartao { width:100% !important; border-radius:0 !important; }
    .miolo { padding:22px 18px !important; }
  }
  @media (prefers-color-scheme: dark) {
    body, .fundo { background:#0e0f1f !important; }
    .linha td { border-bottom-color:#2c2e4a !important; }
    .cartao, .miolo, .rodape { background:#191a30 !important; }
    .txt { color:#e7e8f3 !important; }
    .tit { color:#ffffff !important; }
    .mudo { color:#a9abc6 !important; }
    .rodape { border-top-color:#2c2e4a !important; }
    .btn { background:#ff9900 !important; }
    .btn a { color:#00004d !important; }
    .txt a, .mudo a { color:#ffb84d !important; }
    .caixa-logo { background:#ffffff !important; }
  }
</style>
</head>
<body style="margin:0;padding:0;background:${MARCA.fundo};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escHtml(previa || titulo)}</div>
<table role="presentation" class="fundo" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${MARCA.fundo}" style="background:${MARCA.fundo};">
<tr><td align="center" style="padding:24px 8px;">
<table role="presentation" class="cartao" width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#ffffff" style="width:600px;max-width:600px;background:#ffffff;border-radius:10px;overflow:hidden;border:1px solid ${MARCA.borda};font-family:${MARCA.fonte};">
<tr><td class="caixa-logo" bgcolor="#ffffff" style="padding:22px 28px 18px;background-color:#ffffff;background-image:linear-gradient(#ffffff,#ffffff);">
<a href="${MARCA.site}" style="text-decoration:none;"><img src="${MARCA.logo}" width="160" height="63" alt="Instituto Modal" style="display:block;width:160px;height:auto;border:0;color:${MARCA.azul};font-family:${MARCA.fonte};font-size:18px;font-weight:700;"></a>
</td></tr>
<tr><td height="4" bgcolor="${MARCA.laranja}" style="height:4px;line-height:4px;font-size:0;background:${MARCA.laranja};">&nbsp;</td></tr>
<tr><td class="miolo" style="padding:26px 28px 20px;background:#ffffff;">
${etiqueta ? `<div class="mudo" style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#b36b00;">${escHtml(etiqueta)}</div>` : ''}
<h1 class="tit" style="margin:0 0 16px;font-size:20px;line-height:1.35;font-weight:700;color:${MARCA.azul};">${escHtml(titulo)}</h1>
${blocos}
${botao}
</td></tr>
<tr><td class="rodape" style="padding:16px 28px 20px;background:#ffffff;border-top:1px solid ${MARCA.borda};">
<p class="mudo" style="margin:0;font-size:12px;line-height:1.5;color:${MARCA.cinza};">${rodape}</p>
</td></tr>
</table>
<p class="mudo" style="margin:14px 0 0;font-family:${MARCA.fonte};font-size:12px;color:${MARCA.cinza};">Instituto Modal · <a href="${MARCA.site}" style="color:${MARCA.cinza};">modal.org.br</a></p>
</td></tr>
</table>
</body>
</html>`;
}

// Lógica do subfluxo "Modal – Enviar e-mail": recebe o pedido de envio e devolve o e-mail pronto.
// Depende de layout-email.js (o gerador concatena os dois no nó Code).
//
// Pedido (campos do subfluxo):
//   para, cc, cco, responderPara, nomeRemetente, assunto       (para e assunto obrigatórios)
//   modelo: 'padrao' (layout do Modal) ou 'livre' (corpoHtml enviado como está, ex.: newsletter)
//   etiqueta, titulo, previa, rodape, acaoRotulo, acaoUrl
//   blocos: lista de { tipo, ... } (ver renderBloco); corpoHtml: HTML confiável acrescentado aos blocos
//   texto: versão em texto puro (se vazia, é gerada a partir dos blocos)
//   anexos: nomes dos arquivos (propriedades binárias) separados por vírgula

const RODAPE_PADRAO = 'Mensagem automática do Instituto Modal.';

function listaEnderecos(valor) {
  const itens = (Array.isArray(valor) ? valor : String(valor ?? '').split(/[,;]/))
    .map((s) => String(s).trim())
    .filter(Boolean);
  for (const e of itens) {
    const so = e.match(/<([^>]+)>$/) ? e.match(/<([^>]+)>$/)[1] : e;
    if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(so)) throw new Error(`Endereço de e-mail inválido: "${e}"`);
  }
  return [...new Set(itens)].join(', ');
}

function linkOuTexto(i) {
  if (i && typeof i === 'object') {
    const url = String(i.url ?? '');
    if (/^(https?:|mailto:)/i.test(url)) return `<a href="${escHtml(url)}" style="color:#00004d;font-weight:700;">${escHtml(i.texto ?? url)}</a>`;
    return escHtml(i.texto ?? url);
  }
  return escHtml(i);
}

function textoDe(v) {
  return v === null || v === undefined || v === '' ? '—' : String(v);
}

function renderBloco(b) {
  if (!b || typeof b !== 'object') return { html: '', texto: '' };
  switch (b.tipo) {
    case 'paragrafo':
      return b.html !== undefined
        ? { html: paragrafo(b.html), texto: String(b.html).replace(/<[^>]+>/g, '') }
        : { html: paragrafo(escHtml(b.texto)), texto: String(b.texto ?? '') };
    case 'mudanca':
      return {
        html: paragrafo(`${pilula(b.de, 'antes')} <span class="mudo" style="color:#666666;">&rarr;</span> ${pilula(b.para, 'depois')}`),
        texto: `${b.de} → ${b.para}`,
      };
    case 'subtitulo':
      return {
        html: `<h2 class="tit" style="margin:22px 0 10px;font-size:16px;line-height:1.4;font-weight:700;color:#00004d;">${escHtml(b.texto)}</h2>`,
        texto: String(b.texto ?? '').toUpperCase(),
      };
    case 'aviso':
      return { html: aviso(escHtml(b.texto), b.tom), texto: String(b.texto ?? '') };
    case 'lista': {
      const itens = (b.itens || []).map((i) => `<li style="margin:0 0 6px;">${linkOuTexto(i)}</li>`).join('');
      return {
        html: `<ul class="txt" style="margin:0 0 14px;padding-left:20px;font-size:15px;line-height:1.5;color:#1f2033;">${itens}</ul>`,
        texto: (b.itens || []).map((i) => `- ${typeof i === 'object' && i ? `${i.texto} (${i.url})` : i}`).join('\n'),
      };
    }
    case 'campos': {
      const linhas = (b.itens || []).map((i) => `<tr class="linha">
<td class="mudo" valign="top" style="padding:8px 12px 8px 0;border-bottom:1px solid #e3e5ee;font-size:13px;color:#666666;width:38%;">${escHtml(i.rotulo)}</td>
<td class="txt" valign="top" style="padding:8px 0;border-bottom:1px solid #e3e5ee;font-size:14px;color:#1f2033;white-space:pre-wrap;">${i.url ? linkOuTexto({ texto: textoDe(i.valor), url: i.url }) : escHtml(textoDe(i.valor))}</td>
</tr>`).join('');
      const titulo = b.titulo ? `<div class="tit" style="margin:6px 0 6px;font-size:15px;font-weight:700;color:#00004d;">${escHtml(b.titulo)}</div>` : '';
      return {
        html: `${titulo}<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 16px;border-collapse:collapse;">${linhas}</table>`,
        texto: [b.titulo, ...(b.itens || []).map((i) => `${i.rotulo}: ${textoDe(i.valor)}`)].filter(Boolean).join('\n'),
      };
    }
    case 'botoes': {
      const cel = (b.itens || []).map((i) => {
        const cor = i.tom === 'perigo' ? '#c62828' : '#00004d';
        return `<td${i.tom === 'perigo' ? '' : ' class="btn"'} bgcolor="${cor}" style="border-radius:6px;background:${cor};"><a href="${escHtml(i.url)}" style="display:inline-block;padding:11px 20px;font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:6px;">${escHtml(i.rotulo)}</a></td><td width="10" style="width:10px;">&nbsp;</td>`;
      }).join('');
      return {
        html: `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 18px;"><tr>${cel}</tr></table>`,
        texto: (b.itens || []).map((i) => `${i.rotulo}: ${i.url}`).join('\n'),
      };
    }
    case 'html':
      return { html: String(b.html ?? ''), texto: String(b.html ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() };
    default:
      throw new Error(`Tipo de bloco desconhecido: "${b.tipo}"`);
  }
}

function montarEmail(p) {
  const para = listaEnderecos(p.para);
  if (!para) throw new Error('E-mail sem destinatário (campo "para").');
  const assunto = String(p.assunto ?? '').trim();
  if (!assunto) throw new Error('E-mail sem assunto.');
  const cc = listaEnderecos(p.cc);
  const cco = listaEnderecos(p.cco);
  const responderPara = listaEnderecos(p.responderPara);

  let blocos = p.blocos;
  if (typeof blocos === 'string' && blocos.trim()) blocos = JSON.parse(blocos);
  if (!Array.isArray(blocos)) blocos = [];
  const partes = blocos.map(renderBloco);
  if (p.corpoHtml) partes.push(renderBloco({ tipo: 'html', html: p.corpoHtml }));

  let html;
  if (p.modelo === 'livre') {
    if (!p.corpoHtml) throw new Error('Modelo livre exige "corpoHtml".');
    html = String(p.corpoHtml);
  } else {
    html = layoutEmail({
      etiqueta: p.etiqueta,
      titulo: p.titulo || assunto,
      previa: p.previa,
      blocos: partes.map((x) => x.html).join('\n'),
      acao: p.acaoRotulo && p.acaoUrl ? { rotulo: p.acaoRotulo, url: p.acaoUrl } : null,
      rodape: escHtml(p.rodape || RODAPE_PADRAO),
    });
  }

  const texto = p.texto || [
    p.titulo || assunto,
    ...partes.map((x) => x.texto).filter(Boolean),
    p.acaoRotulo && p.acaoUrl ? `${p.acaoRotulo}: ${p.acaoUrl}` : '',
    p.rodape || RODAPE_PADRAO,
  ].filter(Boolean).join('\n\n');

  const anexos = String(p.anexos ?? '').split(',').map((s) => s.trim()).filter(Boolean).join(',');

  return {
    para, cc, cco, responderPara,
    nomeRemetente: p.nomeRemetente || 'Instituto Modal',
    assunto, html, texto, anexos,
    temAnexos: anexos.length > 0,
  };
}


return $input.all().map((item) => ({
  json: montarEmail(item.json),
  binary: item.binary,
  pairedItem: item.pairedItem,
}));

