    case 'mudanca':
      return {
        html: paragrafo(`${pilula(b.de, 'antes')} <span class="mudo" style="color:#666666;">&rarr;</span> ${pilula(b.para, 'depois')}`),
        texto: `${b.de} → ${b.para}`,
      };
    case 'subtitulo':
      return {
        html: `<h2 class="tit" style="margin:22px 0 10px;font-size:16px;line-height:1.4;font-weight:700;color:#00004d;">${escHtml(b.texto)}</h2>`,
        texto: String(b.texto ?? '').toUpperCase(),
      };
    case 'aviso':
      return { html: aviso(escHtml(b.texto), b.tom), texto: String(b.texto ?? '') };
    case 'lista': {
      const itens = (b.itens || []).map((i) => `<li style="margin:0 0 6px;">${linkOuTexto(i)}</li>`).join('');
      return {
        html: `<ul class="txt" style="margin:0 0 14px;padding-left:20px;font-size:15px;line-height:1.5;color:#1f2033;">${itens}</ul>`,
        texto: (b.itens || []).map((i) => `- ${typeof i === 'object' && i ? `${i.texto} (${i.url})` : i}`).join('\n'),
      };
    }
    case 'campos': {
      const linhas = (b.itens || []).map((i) => `<tr class="linha">
<td class="mudo" valign="top" style="padding:8px 12px 8px 0;border-bottom:1px solid #e3e5ee;font-size:13px;color:#666666;width:38%;">${escHtml(i.rotulo)}</td>
<td class="txt" valign="top" style="padding:8px 0;border-bottom:1px solid #e3e5ee;font-size:14px;color:#1f2033;white-space:pre-wrap;">${i.url ? linkOuTexto({ texto: textoDe(i.valor), url: i.url }) : escHtml(textoDe(i.valor))}</td>
</tr>`).join('');
      const titulo = b.titulo ? `<div class="tit" style="margin:6px 0 6px;font-size:15px;font-weight:700;color:#00004d;">${escHtml(b.titulo)}</div>` : '';
      return {
        html: `${titulo}<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 16px;border-collapse:collapse;">${linhas}</table>`,
        texto: [b.titulo, ...(b.itens || []).map((i) => `${i.rotulo}: ${textoDe(i.valor)}`)].filter(Boolean).join('\n'),
      };
    }
    case 'botoes': {
      const cel = (b.itens || []).map((i) => {
        const cor = i.tom === 'perigo' ? '#c62828' : '#00004d';
        return `<td${i.tom === 'perigo' ? '' : ' class="btn"'} bgcolor="${cor}" style="border-radius:6px;background:${cor};"><a href="${escHtml(i.url)}" style="display:inline-block;padding:11px 20px;font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:6px;">${escHtml(i.rotulo)}</a></td><td width="10" style="width:10px;">&nbsp;</td>`;
      }).join('');
      return {
        html: `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 18px;"><tr>${cel}</tr></table>`,
        texto: (b.itens || []).map((i) => `${i.rotulo}: ${i.url}`).join('\n'),
      };
    }
    case 'html':
      return { html: String(b.html ?? ''), texto: String(b.html ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() };
    default:
      throw new Error(`Tipo de bloco desconhecido: "${b.tipo}"`);
  }
}

function montarEmail(p) {
  const para = listaEnderecos(p.para);
  if (!para) throw new Error('E-mail sem destinatário (campo "para").');
  const assunto = String(p.assunto ?? '').trim();
  if (!assunto) throw new Error('E-mail sem assunto.');
  const cc = listaEnderecos(p.cc);
  const cco = listaEnderecos(p.cco);
  const responderPara = listaEnderecos(p.responderPara);

  let blocos = p.blocos;
  if (typeof blocos === 'string' && blocos.trim()) blocos = JSON.parse(blocos);
  if (!Array.isArray(blocos)) blocos = [];
  const partes = blocos.map(renderBloco);
  if (p.corpoHtml) partes.push(renderBloco({ tipo: 'html', html: p.corpoHtml }));

  let html;
  if (p.modelo === 'livre') {
    if (!p.corpoHtml) throw new Error('Modelo livre exige "corpoHtml".');
    html = String(p.corpoHtml);
  } else {
    html = layoutEmail({
      etiqueta: p.etiqueta,
      titulo: p.titulo || assunto,
      previa: p.previa,
      blocos: partes.map((x) => x.html).join('\n'),
      acao: p.acaoRotulo && p.acaoUrl ? { rotulo: p.acaoRotulo, url: p.acaoUrl } : null,
      rodape: escHtml(p.rodape || RODAPE_PADRAO),
    });
  }

  const texto = p.texto || [
    p.titulo || assunto,
    ...partes.map((x) => x.texto).filter(Boolean),
    p.acaoRotulo && p.acaoUrl ? `${p.acaoRotulo}: ${p.acaoUrl}` : '',
    p.rodape || RODAPE_PADRAO,
  ].filter(Boolean).join('\n\n');

  const anexos = String(p.anexos ?? '').split(',').map((s) => s.trim()).filter(Boolean).join(',');

  return {
    para, cc, cco, responderPara,
    nomeRemetente: p.nomeRemetente || 'Instituto Modal',
    assunto, html, texto, anexos,
    temAnexos: anexos.length > 0,
  };
}


return $input.all().map((item) => ({
  json: montarEmail(item.json),
  binary: item.binary,
  pairedItem: item.pairedItem,
}));
